// src/lib/pdfFonts.ts
// ΠΑΡΑΓΟΜΕΝΟ ΑΡΧΕΙΟ — μην το επεξεργάζεσαι με το χέρι.
//
// DejaVu Sans (κανονική + έντονη), subset για Λατινικά, Ελληνικά (μαζί με
// πολυτονικό), σημεία στίξης, €, •, ☐/☑. Άδεια: Bitstream Vera / DejaVu
// (ελεύθερη χρήση και αναδιανομή). Ενσωματωμένη ως base64 ώστε να μη
// χρειάζεται ανάγνωση αρχείου στο Vercel. Το pdf-lib κρατά στο PDF ΜΟΝΟ τα
// γλυφά που χρησιμοποιούνται (subset: true).
//
// Αναπαραγωγή (fonttools):
//   pyftsubset DejaVuSans.ttf --unicodes="U+0020-007E,U+00A0-00FF,U+0370-03FF,\
//     U+1F00-1FFF,U+2010-2027,U+2030-203A,U+20AC,U+2116,U+2122,U+2190-2193,\
//     U+2212,U+2610-2612,U+2713,U+2714" --layout-features='*' --no-hinting \
//     --desubroutinize --output-file=DejaVuSans-subset.ttf
//   (το ίδιο για DejaVuSans-Bold.ttf) και base64 εδώ.

export const DEJAVU_SANS_B64 =
  "";

export const DEJAVU_SANS_BOLD_B64 =
  "";
